import{_ as i,H as t,f as a,i as s}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"37 | 分布式锁：如何保证Redis分布式锁的高可用和高性能？","description":"","frontmatter":{},"headers":[{"level":2,"title":"能用于实现分布式锁的中间件","slug":"能用于实现分布式锁的中间件","link":"#能用于实现分布式锁的中间件","children":[]},{"level":2,"title":"面试准备","slug":"面试准备","link":"#面试准备","children":[]},{"level":2,"title":"面试思路","slug":"面试思路","link":"#面试思路","children":[{"level":3,"title":"加锁","slug":"加锁","link":"#加锁","children":[]},{"level":3,"title":"亮点 1：等待时间","slug":"亮点-1-等待时间","link":"#亮点-1-等待时间","children":[]},{"level":3,"title":"亮点 2：如何实现等待机制","slug":"亮点-2-如何实现等待机制","link":"#亮点-2-如何实现等待机制","children":[]},{"level":3,"title":"亮点 3：加锁重试","slug":"亮点-3-加锁重试","link":"#亮点-3-加锁重试","children":[]},{"level":3,"title":"锁过期时间","slug":"锁过期时间","link":"#锁过期时间","children":[]},{"level":3,"title":"亮点 1：过期时间应该多长","slug":"亮点-1-过期时间应该多长","link":"#亮点-1-过期时间应该多长","children":[]},{"level":3,"title":"亮点 2：续约机制","slug":"亮点-2-续约机制","link":"#亮点-2-续约机制","children":[]},{"level":3,"title":"亮点 3：中断业务","slug":"亮点-3-中断业务","link":"#亮点-3-中断业务","children":[]},{"level":3,"title":"释放锁","slug":"释放锁","link":"#释放锁","children":[]},{"level":3,"title":"其他亮点","slug":"其他亮点","link":"#其他亮点","children":[]},{"level":3,"title":"Redlock","slug":"redlock","link":"#redlock","children":[]},{"level":3,"title":"性能优化","slug":"性能优化","link":"#性能优化","children":[]},{"level":3,"title":"去分布式锁","slug":"去分布式锁","link":"#去分布式锁","children":[]}]},{"level":2,"title":"面试思路总结","slug":"面试思路总结","link":"#面试思路总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"后端工程师的高阶面经/37｜分布式锁：如何保证Redis分布式锁的高可用和高性能？.md","filePath":"后端工程师的高阶面经/37｜分布式锁：如何保证Redis分布式锁的高可用和高性能？.md","lastUpdated":1795554391000}'),l={name:"后端工程师的高阶面经/37｜分布式锁：如何保证Redis分布式锁的高可用和高性能？.md"};function n(E,e,p,r,o,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="_37-分布式锁-如何保证redis分布式锁的高可用和高性能" tabindex="-1">37 | 分布式锁：如何保证Redis分布式锁的高可用和高性能？ <a class="header-anchor" href="#_37-分布式锁-如何保证redis分布式锁的高可用和高性能" aria-label="Permalink to &quot;37 | 分布式锁：如何保证Redis分布式锁的高可用和高性能？&quot;">​</a></h1><p>你好，我是大明。今天我们来学习一个面试中热度极高的话题——分布式锁。</p><p>分布式锁和分布式事务，可以说是分布式系统里面两个又热又难的话题。从理论上来说，分布式锁和分布式事务都涉及到了很多分布式系统里面的基本概念，所以我们不愁找不到切入点。从实践上来说，分布式锁和分布式事务都是属于一不小心就会出错的技术手段。</p><p>在面试分布式锁的过程中，我发现大部分人只知道很基础的几个点，比如说只能回答出使用SETNX 命令，又或者能答出要设置超时时间。当进一步追问的时候，就不知道了。</p><p>那么今天我就带你全方位学习分布式锁的知识点，确保你在这个话题之下能够赢得竞争优势。</p><h2 id="能用于实现分布式锁的中间件" tabindex="-1">能用于实现分布式锁的中间件 <a class="header-anchor" href="#能用于实现分布式锁的中间件" aria-label="Permalink to &quot;能用于实现分布式锁的中间件&quot;">​</a></h2><p>这一节课的主题是用 Redis 来实现一个分布式锁，但是并不意味着分布式锁只能使用 Redis来实现。</p><p>简单来说，支持排他性操作的中间件都可以作为实现分布式锁的中间件，例如 ZooKeeper、Nacos 等，甚至关系型数据库也可以，比如说利用 MySQL 的 SELECT FOR UPDATE 语法是可以实现分布式锁的。</p><h2 id="面试准备" tabindex="-1">面试准备 <a class="header-anchor" href="#面试准备" aria-label="Permalink to &quot;面试准备&quot;">​</a></h2><p>你在公司里面要收集一些信息。</p><ul><li><p>你们公司有没有使用分布式锁的场景？不用分布式锁行不行？</p></li><li><p>你们使用的分布式锁是怎么实现的？性能怎么样？</p></li><li><p>你使用的分布式锁有没有做什么性能优化？</p></li><li><p>你使用的分布式锁是如何加锁、释放锁的？有没有续约机制？</p></li><li><p>在使用分布式锁的时候，各个环节收到超时响应，你会怎么办？</p></li></ul><p>分布式锁是一个通用的业务解决方案。也就是说，你完全可以研发一个独立的分布式锁，提供给各个业务线使用。所以你在简历中或者自我介绍的时候就可以强调自己开发了一个独立的分布式锁框架，不仅实现了基本功能，还做了一定的性能优化。</p><p>当然，讨论到下面这些话题的时候，你也可以尝试把话题引导到分布式锁上。</p><ul><li><p>你和面试官聊到了 ZooKeeper 等适合用来实现分布式锁的中间件的时候，可以提起你利用Redis 实现了一个分布式锁。</p></li><li><p>你和面试官聊到了 singltflight 模式，可以提起你用 Singleflight 来优化过分布式锁的性能。</p></li><li><p>你和面试官聊到了过期时间，可以提起在分布式锁里也要设置一个合适的过期时间。</p></li><li><p>你和面试官聊到了租约之类的机制，可以提起分布式锁也要实现类似的机制，防止锁持有者崩溃，无法释放锁。</p></li></ul><h2 id="面试思路" tabindex="-1">面试思路 <a class="header-anchor" href="#面试思路" aria-label="Permalink to &quot;面试思路&quot;">​</a></h2><p>整个面试思路就是层层深入，将分布式锁的各个点都讨论清楚。</p><h3 id="加锁" tabindex="-1">加锁 <a class="header-anchor" href="#加锁" aria-label="Permalink to &quot;加锁&quot;">​</a></h3><p>要使用 Redis 实现分布式锁，首先要明确一个分布式锁在 Redis 上究竟意味着什么。答案也很简单，所谓的分布式锁在 Redis 上就是一个普通的键值对。</p><p>那么为什么一个普通的键值对也可以看成 Redis 的分布式锁呢？奥妙就在于分布式锁的本质——排他性，就是只要你能够借助 Redis 达成排他的效果就可以了。</p><p>而在 Redis 上怎么能够达到这种排他的效果？用 SETNX 命令就可以做到。也就是说，如果一个线程能够用 SETNX 成功地在 Redis 上设置好一个键值对，那么在它删除这个键值对之前，别的线程都没办法再设置同样的键值对。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/1.png" alt=""></a></p><p>所以，加锁就是调用 SETNX 命令，而释放锁就是执行 DEL 命令。你在面试的过程中要先简明扼要地说清楚锁的实质，还有加锁和释放锁是什么。</p><ul><li><p>利用 Redis 来实现分布式锁的时候，所谓的锁就是一个普通的键值对。而加锁就是使用SETNX 命令，排他地设置一个键值对。如果 SETNX 命令设置键值对成功了，那么说明加</p></li><li><p>锁成功。如果没有设置成功，说明这个时候有人持有了锁，需要等待别人释放锁。而相应地，释放锁就是删除这个键值对。</p></li></ul><p>接下来你可以等面试官主动询问这个过程中的细节。</p><h3 id="亮点-1-等待时间" tabindex="-1">亮点 1：等待时间 <a class="header-anchor" href="#亮点-1-等待时间" aria-label="Permalink to &quot;亮点 1：等待时间&quot;">​</a></h3><p>在前面回答中，你提到加锁失败了，就要等一段时间，等别人释放锁。那么面试官可能问你，究竟该等多长时间？理论上来说，是尽可能在等待的这段时间内拿到锁。因此等待的时间就是一个锁会被持有的时间。</p><ul><li>当加锁失败的时候，这个等待时间是要根据锁的持有时间来设置的。比如说如果预计 99%的锁持续时间是一秒钟，那么我们就可以把这个等待时间设置成一秒钟。</li></ul><p>在说完了如何确定等待时间之后，接下来就可以讨论怎么实现这种等待机制。</p><h3 id="亮点-2-如何实现等待机制" tabindex="-1">亮点 2：如何实现等待机制 <a class="header-anchor" href="#亮点-2-如何实现等待机制" aria-label="Permalink to &quot;亮点 2：如何实现等待机制&quot;">​</a></h3><p>面试官大概率会进一步追问，你说的等待究竟是怎么实现的？这也有两种方案，轮询和监听删除事件。</p><ul><li>等待也有两种实现方式。第一种方式就是轮询，比如说在加锁失败之后，每睡眠 100 毫秒就尝试加锁一次，直到成功或者整个等待时间超过一秒钟。第二种方式是监听删除事件，也就是在加锁失败之后立刻订阅这个键值对。当键值对被删除的时候就说明锁被释放了，这个时候再次尝试加锁。监听删除事件总的来说，实时性比较好，但是实现起来比较麻烦。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/2.png" alt=""></a></p><p>这个示意图只是为了方便你理解，而在实际的实现中，发现锁被人设置了和订阅是要做成一个整体的，不然就会有并发问题。</p><h3 id="亮点-3-加锁重试" tabindex="-1">亮点 3：加锁重试 <a class="header-anchor" href="#亮点-3-加锁重试" aria-label="Permalink to &quot;亮点 3：加锁重试&quot;">​</a></h3><p>就算是正常的加锁也有可能遇到超时的问题，怎么办？这个问题棘手之处在于你也不知道出现超时的时候，究竟有没有加锁成功。</p><p>按照之前我们遇到超时的一般思路，就是直接重试。但是重试的逻辑比较复杂，分成几种情况。</p><ol><li>第一次调用的时候，并没有成功。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/3.png" alt=""></a></p><ol start="2"><li>第一次调用的时候，加锁成功了。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/4.png" alt=""></a></p><ol start="3"><li>第一次调用的时候，加锁失败了，并且现在别的线程持有锁。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/5.png" alt=""></a></p><p>你在这三张图里应该注意到了，重试的一个核心是要知道自己究竟有没有加锁成功。所以，你在加锁的时候，键值对里的值应该可以标识锁是谁加的。比如说，使用 UUID。也就是你重试的时候还带着上次的 UUID，如果 Redis 里键值对存在，并且值正好是你的 UUID，那就说明是你的锁。</p><p>所以你可以这么介绍你的方案。</p><ul><li><p>分布式锁也可以考虑提供重试功能。比如说加锁的时候收到了超时响应，就可以发起重试。假如说我要给 key1 加分布式锁，随机生成了一个 UUID value1 作为值，那么重试的基本逻辑是这样的：</p></li><li><p>检查一下 Redis 里是否存在 key1。如果 key1 不存在，那么说明上一次调用没有加锁成1.功。</p></li><li><p>如果 key1 存在，检查值是不是 value1。如果是 value1，那么说明我上一次加锁成功2.了。考虑到距离重试的时候已经过去了一段时间，所以需要重置一下过期时间。</p></li><li><p>值并不是 value1，这个时候说明已经有别人拿着锁了，也就说明加锁失败了。3.</p></li></ul><p>在实践中，因为 Redis 本身性能很好，所以最多重试一两次。但是，如果从理论上分析，就有重试一直都超时的可能。这时候会发生什么？</p><ul><li>如果重试一直都超时，这个时候也不需要额外处理。因为如果之前加锁已经成功了，那么无非就是过期时间到了，锁自然失效。如果之前没有加锁成功，就更没事了，别的线程需要的时候就可以拿到锁。</li></ul><p>在这个回答里面，你就提到了一个概念：过期时间。为什么分布式锁需要一个过期时间呢？</p><h3 id="锁过期时间" tabindex="-1">锁过期时间 <a class="header-anchor" href="#锁过期时间" aria-label="Permalink to &quot;锁过期时间&quot;">​</a></h3><p>如果你的机器永远不会出问题，网络也永远不会出问题，那么分布式锁用 Redis 的 SETNX 和DEL 命令就足够了。然而，现实中这个假设显然是不成立的，所以你就要考虑这么一个问题，万一你加锁的那个线程崩溃了呢？比如说，它所在的机器整个崩溃了，应该怎么办？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/6.png" alt=""></a></p><p>你抓住关键词没人释放来回答。</p><ul><li>在使用分布式锁的时候，分布式锁的持有者有可能宕机，这会导致整个锁既没有人能够获得，也没有人能够释放。在这种情况下，就可以考虑给分布式锁加一个过期时间。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/7.png" alt=""></a></p><h3 id="亮点-1-过期时间应该多长" tabindex="-1">亮点 1：过期时间应该多长 <a class="header-anchor" href="#亮点-1-过期时间应该多长" aria-label="Permalink to &quot;亮点 1：过期时间应该多长&quot;">​</a></h3><p>只要涉及这种过期时间的问题，面试官肯定会问，这个过期时间应该设置成多长？</p><ul><li><p>这个过期时间应该根据业务来设置。比如说，如果在拿到锁之后，99% 的业务都可以在 1秒内完成，那么就可以把过期时间设置得比 1 秒长一些，比如说设置成 2 秒。保险起见，设置成 10 秒甚至一分钟也没多大关系。</p></li><li><p>过期时间主要是为了防止系统宕机而引入的，而大部分情况下，锁都能被正常释放掉，所以把过期时间设置得长一些也没什么问题。</p></li></ul><p>我注意到，很多公司的分布式锁也就是实现到了这一步。所以你可以考虑进一步刷亮点。</p><ul><li>总的来说，不管过期时间设置成多长，都可能遇到业务没能在持有分布式锁期间完成的情况。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/8.png" alt=""></a></p><p>这也是为了引导面试官发问。这种情况究竟该怎么解决呢？答案是续约。</p><h3 id="亮点-2-续约机制" tabindex="-1">亮点 2：续约机制 <a class="header-anchor" href="#亮点-2-续约机制" aria-label="Permalink to &quot;亮点 2：续约机制&quot;">​</a></h3><p>所谓续约是指设置了过期时间之后，在快要过期的时候，再次延长这个过期时间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/9.png" alt=""></a></p><ul><li>为了防止出现总有业务不能在锁过期时间内结束的问题，可以考虑引入续约机制。也就是在分布式锁快要过期的时候就重置一下过期时间。比如说一开始过期时间设置的是 1 分钟，那么可以在 50 秒之后再次把过期时间重置为 1 分钟。理论上来说，只需要确保在剩余过期时间内能够续约成功，就可以了。比如说这里预留了 10 秒，那么就算第一次续约失败，也有足够的时间进行重试。</li></ul><p>这时候又会出现新的问题，如果重试之后，续约都失败了怎么办？这就要看你的业务特性了。</p><ul><li><p>如果不断重试之后，续约都失败了，那么这个时候就要根据业务来决定采取保守策略还是激进策略了。如果你对排他性要求得非常严格，那么这个时候你只能考虑中断业务。因为你可能续约失败了，那么接下来就会有人拿到分布式锁。所以你的业务不能继续执行，这也就是保守策略。</p></li><li><p>如果你觉得这种非常偶然的续约失败是可以接受的，那么你还是可以继续执行业务，当然这可能引起数据不一致的问题，这也就是激进方案。</p></li></ul><p>这里你提到了中断业务，这也就是你接下来要刷的另外一个亮点，如何中断业务。</p><h3 id="亮点-3-中断业务" tabindex="-1">亮点 3：中断业务 <a class="header-anchor" href="#亮点-3-中断业务" aria-label="Permalink to &quot;亮点 3：中断业务&quot;">​</a></h3><p>之前你已经在超时控制里面接触过中断业务了，分布式锁其实也面临着一样的困境。</p><ul><li>在分布式锁出了问题的时候，中断业务也是一个很困难的事情。分布式锁并不能直接帮你中断业务，它只能给你发一个信号，告诉你发生了什么糟糕的事情。比如说分布式锁在续约失败的时候，给你发了一个信号。这个时候是否中断业务完全是看你的业务代码是如何实现的。举个例子来说，如果你的业务是一个大循环，那么你可以在每个循环开始的时候，检测一下有没有收到什么信号。如果收到了需要中断的信号，那么就退出循环。</li></ul><p>伪代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for condition {</span></span>
<span class="line"><span>// 中断业务执行</span></span>
<span class="line"><span> if interrupted {</span></span>
<span class="line"><span>   break;</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span> // 你的业务逻辑</span></span>
<span class="line"><span> DoSomething()</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>如果你的业务没有循环，那么你可以在每一个关键步骤之后都检测一下有没有收到信号，然后考虑要不要中断业务。</li></ul><p>伪代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step1()</span></span>
<span class="line"><span>if interrupted {</span></span>
<span class="line"><span> return</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>step2()</span></span>
<span class="line"><span>if interrupted {</span></span>
<span class="line"><span> return</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>最后你要总结拔高一下。</p><ul><li>这种中断业务的问题，在微服务超时控制里面也会遇到，不过也是无解的问题，因为微服务框架也做不到帮你自动中断业务。</li></ul><h3 id="释放锁" tabindex="-1">释放锁 <a class="header-anchor" href="#释放锁" aria-label="Permalink to &quot;释放锁&quot;">​</a></h3><p>正常来说，释放锁都不会有什么问题。但是在一些特殊场景下，释放锁也可能会有问题。比如说线程 1 加了锁，结果 Redis 崩溃了又恢复过来，这时候线程 2 也加了同一把锁。</p><p>当线程 1 执行完毕之后，去释放锁就会把线程 2 的锁也释放掉。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/10.png" alt=""></a></p><p>所以在释放锁的时候，都要确认这个锁是不是自己的。</p><ul><li>在释放锁的时候，要先确认锁是不是自己加的，防止因为系统故障或者有人手动操作了Redis 导致锁被别人持有了。确认锁的方法也很简单，就是比较一下键值对里的值是不是自己设置的。这也要求在加锁设置键值对的时候使用唯一的值，比如说用 UUID。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/11.png" alt=""></a></p><h3 id="其他亮点" tabindex="-1">其他亮点 <a class="header-anchor" href="#其他亮点" aria-label="Permalink to &quot;其他亮点&quot;">​</a></h3><p>这里我再补充三个亮点，一个是非常热门的话题 Redlock，另外两个是性能优化的方案。你可以尝试把性能优化的亮点纳入到你优化整个系统性能的方案中。</p><h3 id="redlock" tabindex="-1">Redlock <a class="header-anchor" href="#redlock" aria-label="Permalink to &quot;Redlock&quot;">​</a></h3><p>在实现分布式锁的时候，有一个问题必须要考虑：如果 Redis 崩溃了怎么办？在释放锁那里，你已经看到，如果 Redis 崩溃了再恢复过来的时候，锁就有可能被别人拿走。怎么解决这种问题呢？</p><p>首先，Redis 的主从切换机制是解决不了这个问题的，因为 Redis 的主从同步是异步的。也就是说当你拿到一个分布式锁的时候，这个锁还没有同步到从节点，主节点就可能崩溃了。这个时候从节点被提升成主节点，里面并没有你的分布式锁，所以别人就可以拿到分布式锁。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/12.png" alt=""></a></p><p>为了解决这个问题，就有了 Redlock 算法。你只需要掌握 Redlock 的基本概念就可以，不需要深入去研究。原因也很简单，就是目前绝大部分公司使用的分布式锁，都没有按照 Redlock算法来实现，因为 Redlock 成本高，性能也比较差。</p><p>Redlock 的思想说起来也很简单，用一句话概括就是多数原则。也就是说，你加锁的时候要在多个独立的 Redis 节点上同时加锁。当大多数节点都告诉你加锁成功的时候，就说明你加锁成功了。举例来说，如果你同时在 5 个节点上加锁，那么大多数就意味着至少 3 个节点成功才算加锁成功。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/13.png" alt=""></a></p><p>在这个过程中，假设说你的锁过期时间是 10 秒，加锁花了 1 秒钟，那么你就只剩下 9 秒钟。如果加锁失败，还要在所有的节点上释放锁。比如说 4 个节点告诉你成功了，1 个节点超时了，这种时候你需要在 5 个节点上一起释放锁。</p><p>这个问题一般会在分布式锁面试的最后出现，面试官可能会随口问一下，看看你知不知道Redlock 这回事。</p><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><p>其实分布式锁能够做的优化不多。一个思路是优化 Redis 本身的性能，另外一个思路是减少分布式锁的竞争。在高并发的环境下，可以考虑使用 Singleflight 模式来优化分布式锁。</p><p>Singleflight 模式我们前面已经接触过了。在缓存模式里，Singleflight 模式可以确保同一个 key在一个实例上，只有一个线程去回查数据库。类似地，在分布式锁中应用 Singleflight 模式则是为了确保针对同一个锁一个实例只有一个线程去获取分布式锁。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/14.png" alt=""></a></p><ul><li><p>要想优化分布式锁的性能，一方面是考虑优化 Redis 本身的性能，比如说启用单独的 Redis集群，这可以有效防止别的业务操作 Redis，影响加锁和释放锁的性能。另外一方面则是可以考虑减少分布式锁的竞争，比如说使用 Singleflight 模式。也就是针对同一把锁，每个实例内部先选出一个线程去获得锁。</p></li><li><p>假设有 2 个实例，每个实例上各有 10 个线程要去获得 key1 上的分布式锁。在不使用Singleflight 模式的情况下，总共有 20 个线程会去竞争分布式锁。但是在使用 Singleflight模式之后，最终只有 2 个线程去竞争分布式锁。竞争越激烈，这种方案的效果越好。如果没什么并发的话，那么就基本没什么效果。</p></li></ul><p>这里还有一种更加激进的优化方案。</p><ul><li>在实例拿到了分布式锁之后，释放锁之前先看看本地有没有别的线程也需要同一把分布式锁。如果有，就直接转交给本地的线程，进一步减少加锁和释放锁的开销。这种优化手段同样是在竞争越激烈的场景，效果越好。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/15.png" alt=""></a></p><p>最后不要忘了补充一下，也就是分布式锁不到逼不得已，就不要使用。</p><ul><li>分布式锁不管怎么优化，都有性能损耗。所以原则上来说，能不用分布式锁就不用分布式锁。</li></ul><p>这句话也是为了引出下一个亮点，去分布式锁。</p><h3 id="去分布式锁" tabindex="-1">去分布式锁 <a class="header-anchor" href="#去分布式锁" aria-label="Permalink to &quot;去分布式锁&quot;">​</a></h3><p>在一些场景下是可以考虑去掉分布式锁的。严格来说，应该是原本这些场景就不该用分布式锁，现在是回归本源了。</p><p>那究竟怎么去分布式锁呢？第一种思路：用数据库乐观锁来取代分布式锁。</p><ul><li>第一种思路就是可以尝试用数据库乐观锁来取代分布式锁。比如说一些场景是加了分布式锁之后执行一些计算，最后更新数据库。在这种场景下，完全可以抛弃分布式锁，直接计算，最后计算完成之后，利用乐观锁来更新数据库。缺点就是没有分布式锁的话，可能会有多个线程在计算。但是问题不大，因为只要最终更新数据库控制住了并发，就没关系。</li></ul><p>还有另外一种思路。</p><ul><li>第二种思路是利用一致性哈希负载均衡算法。在使用这种算法的时候，同一个业务的请求肯定发到同一个节点上。这时候就没必要使用分布式锁了，本地直接加锁，或者用Singleflight 模式就可以。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/16.png" alt=""></a></p><h2 id="面试思路总结" tabindex="-1">面试思路总结 <a class="header-anchor" href="#面试思路总结" aria-label="Permalink to &quot;面试思路总结&quot;">​</a></h2><p>这一节课我们聊到了实现一个分布式锁要考虑的各种细节。一个分布式锁在 Redis 上就是一个普通的键值对。加锁的时候使用 SETNX 命令，并且要考虑如果加锁没成功要等多久，是轮询等待还是监听锁释放，加锁超时怎么重试等问题。</p><p>为了防止锁持有者崩溃导致没有人释放锁，都会给锁设置一个过期时间，这里你要考虑怎么确定合理的过期时间。不过就算是充分考虑到了各种异常情况，业务都还是有可能在过期时间到了的时候都还没执行完，所以需要考虑续约。而续约本身也有可能失败，那么就要根据业务要求来决定是继续执行还是中断。中断业务一直是一个老大难的问题，目前也只能是靠人在代码里面主动检测。</p><p>在释放锁的时候，要考虑到中间 Redis 崩溃又恢复导致分布式锁被别人拿到了的情况，所以在释放锁之前，也要先检测是不是自己的锁。</p><p>最后我还给出了三个亮点内容，第一个是 Redlock，这个你只需要有一个基本概念就可以了。另外两个都是尝试优化性能，优化分布式锁的性能主要是用 Singleflight 来减少竞争。而优化系统本身的性能，也就是尝试把分布式锁去掉，可以考虑使用数据库乐观锁或者一致性哈希负载均衡来取代分布式锁。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/37/17.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后请你来思考两个问题。</p><ul><li><p>分布式锁释放锁的时候也可以考虑重试，那么这个阶段在重试的时候要考虑什么情况？</p></li><li><p>你还有没有优化过分布式锁的案例？可以是优化分布式锁本身，也可以是去除业务中的分布式锁。</p></li></ul><p>欢迎你把自己的案例分享到评论区，我们一起讨论，也欢迎你把这节课的内容分享给需要的朋友，我们下节课再见！</p>`,124)])])}const g=i(l,[["render",n]]);export{A as __pageData,g as default};
